const {normalizeTheme,resolveEffectiveTheme,getThemeCapabilities}=require('@scaleup/storefront-theme');
const {PREBUILT_THEMES,resolvePrebuiltTheme}=require('@scaleup/storefront-theme/prebuilt');
const content={hero:{title:'Controlled merchant hero',subtitle:'Same revision and content',imageUrl:'/tests/fixtures/theme-media.svg'},footer:{text:'Controlled merchant footer'},homepageSections:[{id:'categories',type:'CategoryList'},{id:'featured',type:'FeaturedProducts',settings:{productIds:['product-1']}},{id:'story',type:'BrandStory',settings:{text:'Controlled story',imageUrl:'/tests/fixtures/theme-media.svg'}}]};
function capture(){return PREBUILT_THEMES.filter(p=>p.id!=='atelier-editorial').map(definition=>{const resolved=resolvePrebuiltTheme({presetId:definition.id,currentTheme:content,appliedAt:'2026-10-20T00:00:00.000Z'});return {id:definition.id,version:definition.version,definition,rawPublishedSnapshot:JSON.parse(JSON.stringify(resolved)),normalized:normalizeTheme(resolved),capabilities:Object.fromEntries(['full','limited','none'].map(access=>[access,getThemeCapabilities(resolved,{storeBuilderAccess:access})])),effective:Object.fromEntries(['full','limited','none'].map(access=>[access,resolveEffectiveTheme(resolved,{shopName:'Fixture store',planAccess:{storeBuilderAccess:access}})]))};});}
module.exports={capture};
if(require.main===module)process.stdout.write(JSON.stringify(capture(),null,2)+'\n');
